'use client';

import * as React from 'react';
import {createComponent, type EventName} from '@lit/react';
import '@material/web/labs/gb/components/button/md-gb-button.js';
import {ButtonElement} from '@material/web/labs/gb/components/button/button-element.js';

/**
 * A Material Design button. Wraps <md-gb-button>.
 * Docs: https://material-web.dev/3.0/components/button/
 */
export const MdButton = createComponent({
  react: React,
  tagName: 'md-gb-button',
  elementClass: ButtonElement,
  events: {
    onChange: 'change' as EventName<Event>,
    onInput: 'input' as EventName<InputEvent>,
  },
});

export type MdButtonProps = React.ComponentProps<typeof MdButton>;
